import{_ as a,o as i,c as t,am as r}from"./chunks/framework.CHDNaA4u.js";const h=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),n={name:"glossaire.md"};function o(s,e,l,u,d,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="accessibilite-aa-wcag" tabindex="-1">Accessibilité AA (WCAG) <a class="header-anchor" href="#accessibilite-aa-wcag" aria-label="Permalink to &quot;Accessibilité AA (WCAG)&quot;">​</a></h3><p>Niveau de règles qui rend un écran utilisable par tous, y compris avec un lecteur d&#39;écran ou au clavier : contraste, libellés, ordre de lecture. Les WCAG sont les règles internationales de référence.</p><h3 id="anonymiser" tabindex="-1">Anonymiser <a class="header-anchor" href="#anonymiser" aria-label="Permalink to &quot;Anonymiser&quot;">​</a></h3><p>Retirer d&#39;un texte tout ce qui permet de reconnaître une personne (nom, e-mail, téléphone, numéro de chambre, date précise…), en le remplaçant par un repère comme [CLIENT].</p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>Point d&#39;entrée par lequel un logiciel en interroge un autre pour échanger des données. Sa disponibilité dit si ce service répond.</p><h3 id="arbitrage" tabindex="-1">Arbitrage <a class="header-anchor" href="#arbitrage" aria-label="Permalink to &quot;Arbitrage&quot;">​</a></h3><p>Décision entre plusieurs options qui ne tiennent pas toutes dans la capacité disponible.</p><h3 id="assistant" tabindex="-1">Assistant <a class="header-anchor" href="#assistant" aria-label="Permalink to &quot;Assistant&quot;">​</a></h3><p>Le produit qu&#39;on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d&#39;un modèle.</p><h3 id="avoir" tabindex="-1">Avoir <a class="header-anchor" href="#avoir" aria-label="Permalink to &quot;Avoir&quot;">​</a></h3><p>Document comptable qui annule ou corrige une facture déjà émise : une facture émise ne se modifie pas.</p><h3 id="business-case" tabindex="-1">Business case <a class="header-anchor" href="#business-case" aria-label="Permalink to &quot;Business case&quot;">​</a></h3><p>Dossier qui compare les options d&#39;une initiative : coûts, bénéfices attendus, risques, hypothèses et inconnues.</p><h3 id="capacite" tabindex="-1">Capacité <a class="header-anchor" href="#capacite" aria-label="Permalink to &quot;Capacité&quot;">​</a></h3><p>Quantité de travail que l&#39;équipe peut prendre dans un sprint donné, compte tenu des absences.</p><h3 id="cas-limite" tabindex="-1">Cas limite <a class="header-anchor" href="#cas-limite" aria-label="Permalink to &quot;Cas limite&quot;">​</a></h3><p>Situation inhabituelle où la règle ne s&#39;applique pas comme d&#39;habitude : paiement refusé, demande annulée, article indisponible…</p><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>Question de contrôle à la fin d&#39;un exercice. Ta réponse reste dans ce navigateur.</p><h3 id="cmdb" tabindex="-1">CMDB <a class="header-anchor" href="#cmdb" aria-label="Permalink to &quot;CMDB&quot;">​</a></h3><p>Base qui recense les applications et composants du système d&#39;information, leurs propriétaires et leurs dépendances (par exemple dans ServiceNow).</p><h3 id="connecteur" tabindex="-1">Connecteur <a class="header-anchor" href="#connecteur" aria-label="Permalink to &quot;Connecteur&quot;">​</a></h3><p>Logiciel qui relie deux systèmes pour qu&#39;ils échangent des données : le connecteur PMS relie Lanterne au système de gestion de l&#39;hôtel. Un outil d&#39;IA peut aussi avoir des connecteurs vers Jira, GitLab ou ServiceNow : ils ne s&#39;utilisent que s&#39;ils sont autorisés.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="contre-signal" tabindex="-1">Contre-signal <a class="header-anchor" href="#contre-signal" aria-label="Permalink to &quot;Contre-signal&quot;">​</a></h3><p>Donnée qui va contre l&#39;idée qu&#39;on défend (des clients qui préfèrent un contact humain, par exemple). On la garde et on la montre.</p><h3 id="critere-d-acceptation" tabindex="-1">Critère d&#39;acceptation <a class="header-anchor" href="#critere-d-acceptation" aria-label="Permalink to &quot;Critère d&#39;acceptation&quot;">​</a></h3><p>Condition vérifiable qu&#39;une user story doit remplir, souvent écrite « Étant donné…, quand…, alors… ».</p><h3 id="derive-de-contexte" tabindex="-1">Dérive de contexte <a class="header-anchor" href="#derive-de-contexte" aria-label="Permalink to &quot;Dérive de contexte&quot;">​</a></h3><p>Session qui se dégrade quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : elle reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="design-system" tabindex="-1">Design system <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design system&quot;">​</a></h3><p>Bibliothèque partagée de composants d&#39;écran et de règles d&#39;usage (ici, Lueur). On n&#39;utilise que ses composants ; un besoin qu&#39;elle ne couvre pas se signale.</p><h3 id="discovery-decouverte" tabindex="-1">Discovery (découverte) <a class="header-anchor" href="#discovery-decouverte" aria-label="Permalink to &quot;Discovery (découverte)&quot;">​</a></h3><p>Travail pour comprendre les besoins des clients (retours, entretiens, données) avant de choisir quoi construire.</p><h3 id="dod-definition-of-done" tabindex="-1">DoD (Definition of Done) <a class="header-anchor" href="#dod-definition-of-done" aria-label="Permalink to &quot;DoD (Definition of Done)&quot;">​</a></h3><p>Liste de critères qu&#39;un travail doit remplir pour être considéré comme terminé.</p><h3 id="dor-definition-of-ready" tabindex="-1">DoR (Definition of Ready) <a class="header-anchor" href="#dor-definition-of-ready" aria-label="Permalink to &quot;DoR (Definition of Ready)&quot;">​</a></h3><p>Liste de critères qu&#39;un besoin ou une user story doit remplir pour être pris en développement.</p><h3 id="epopee" tabindex="-1">Épopée <a class="header-anchor" href="#epopee" aria-label="Permalink to &quot;Épopée&quot;">​</a></h3><p>Grand ensemble de travail découpé en plusieurs user stories (« epic » dans Jira).</p><h3 id="fuite-de-donnees" tabindex="-1">Fuite de données <a class="header-anchor" href="#fuite-de-donnees" aria-label="Permalink to &quot;Fuite de données&quot;">​</a></h3><p>Données confidentielles envoyées à un assistant non maîtrisé (version grand public).</p><h3 id="garde-fou" tabindex="-1">Garde-fou <a class="header-anchor" href="#garde-fou" aria-label="Permalink to &quot;Garde-fou&quot;">​</a></h3><p>Indicateur surveillé pour vérifier qu&#39;un progrès ne se fait pas au détriment d&#39;autre chose.</p><h3 id="grounding" tabindex="-1">Grounding <a class="header-anchor" href="#grounding" aria-label="Permalink to &quot;Grounding&quot;">​</a></h3><p>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</p><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>Réponse fausse mais présentée avec assurance et vraisemblance.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA avant qu&#39;elle soit utilisée.</p><h3 id="instructions-personnalisees-assistant-personnalise" tabindex="-1">Instructions personnalisées / assistant personnalisé <a class="header-anchor" href="#instructions-personnalisees-assistant-personnalise" aria-label="Permalink to &quot;Instructions personnalisées / assistant personnalisé&quot;">​</a></h3><p>Consignes enregistrées une fois et réappliquées : toujours (instructions personnalisées) ou dans un espace dédié (GPT, Projet Claude, agent Copilot).</p><h3 id="kpi" tabindex="-1">KPI <a class="header-anchor" href="#kpi" aria-label="Permalink to &quot;KPI&quot;">​</a></h3><p>Indicateur de suivi d&#39;une activité (volume, délai, taux). Tous les KPI ne sont pas des résultats clés.</p><h3 id="kr-resultat-cle" tabindex="-1">KR (résultat clé) <a class="header-anchor" href="#kr-resultat-cle" aria-label="Permalink to &quot;KR (résultat clé)&quot;">​</a></h3><p>Résultat mesurable qui dit si un objectif est atteint. Il mesure un effet, pas un livrable.</p><h3 id="merge-request-mr-ou-pull-request" tabindex="-1">Merge request (MR) ou pull request <a class="header-anchor" href="#merge-request-mr-ou-pull-request" aria-label="Permalink to &quot;Merge request (MR) ou pull request&quot;">​</a></h3><p>Demande d&#39;intégrer une modification au code du produit. Fusionnée : la modification est intégrée ; brouillon : rien n&#39;est encore livré.</p><h3 id="okr" tabindex="-1">OKR <a class="header-anchor" href="#okr" aria-label="Permalink to &quot;OKR&quot;">​</a></h3><p>Objectifs et résultats clés : un objectif qualitatif, et deux à quatre résultats clés mesurables.</p><h3 id="pms" tabindex="-1">PMS <a class="header-anchor" href="#pms" aria-label="Permalink to &quot;PMS&quot;">​</a></h3><p>Système de gestion de l&#39;hôtel : réservations, état des chambres, note du client.</p><h3 id="portefeuille" tabindex="-1">Portefeuille <a class="header-anchor" href="#portefeuille" aria-label="Permalink to &quot;Portefeuille&quot;">​</a></h3><p>Ensemble des produits d&#39;un même domaine, dont les priorités et les moyens sont arbitrés ensemble (ici, le portefeuille Séjour).</p><h3 id="pre-autorisation" tabindex="-1">Pré-autorisation <a class="header-anchor" href="#pre-autorisation" aria-label="Permalink to &quot;Pré-autorisation&quot;">​</a></h3><p>Montant réservé sur la carte du client à son arrivée, encaissé au moment de régler la note.</p><h3 id="preproduction" tabindex="-1">Préproduction <a class="header-anchor" href="#preproduction" aria-label="Permalink to &quot;Préproduction&quot;">​</a></h3><p>Environnement qui reproduit la production pour tester avant la mise en service ; les vrais clients n&#39;y ont pas accès.</p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>La demande envoyée au modèle, consignes comprises.</p><h3 id="recette" tabindex="-1">Recette <a class="header-anchor" href="#recette" aria-label="Permalink to &quot;Recette&quot;">​</a></h3><p>Vérification, avant la mise en service, que ce qui a été développé respecte les critères d&#39;acceptation. L&#39;environnement de recette sert à ces essais.</p><h3 id="roadmap-feuille-de-route" tabindex="-1">Roadmap (feuille de route) <a class="header-anchor" href="#roadmap-feuille-de-route" aria-label="Permalink to &quot;Roadmap (feuille de route)&quot;">​</a></h3><p>Ce que l&#39;équipe prévoit de faire maintenant, ensuite et plus tard, et pourquoi.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (tool calling).</p><h3 id="transcription" tabindex="-1">Transcription <a class="header-anchor" href="#transcription" aria-label="Permalink to &quot;Transcription&quot;">​</a></h3><p>Texte produit automatiquement à partir de l&#39;enregistrement d&#39;une réunion. Elle peut contenir des trous et des erreurs.</p><h3 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h3><p>Description courte d&#39;un besoin du point de vue de l&#39;utilisateur : « En tant que…, je veux…, afin de… ».</p><h3 id="velocite" tabindex="-1">Vélocité <a class="header-anchor" href="#velocite" aria-label="Permalink to &quot;Vélocité&quot;">​</a></h3><p>Quantité de travail, en points, que l&#39;équipe termine en moyenne par sprint.</p>',91)])])}const m=a(n,[["render",o]]);export{h as __pageData,m as default};
